[Fact]
public async Task DelayAsync_WithNonCancelledToken_CompletesAfterSpecifiedDelay()
{
    // Arrange
    var delayProvider = new DelayProvider();
    var cts = new CancellationTokenSource();
    int delayMs = 100;
    
    // Act
    var sw = System.Diagnostics.Stopwatch.StartNew();
    await delayProvider.DelayAsync(delayMs, cts.Token);
