[Fact]
public async Task DelayAsync_WithMaxIntValue_ShouldDelayForLongPeriod()
{
    // Arrange
    var delayProvider = new DelayProvider();
    var startTime = DateTime.UtcNow;
    var cancellationTokenSource = new CancellationTokenSource(TimeSpan.FromSeconds(1));

    // Act & Assert
    await Assert.ThrowsAsync<TaskCanceledException>(async () =>
    {
        await delayProvider.DelayAsync(int.MaxValue, cancellationTokenSource.Token);
    });

    var elapsedTime = DateTime.UtcNow - startTime;

    Assert.True(elapsedTime >= TimeSpan.FromSeconds(1), 
        $"The delay should have lasted at least 1 second, but it only lasted {elapsedTime.TotalSeconds} seconds.");

